# Generates simple flat illustrations (800x460 SVG) for each place in places.jsonl -> art/p-NN.svg
import json, os, random, math
os.makedirs("art", exist_ok=True)
SKY={"gate":"#dfe7d8","play":"#f3e3c3","water":"#d7ebf0","field":"#e6edd2","shelter":"#efe1cf","restroom":"#e4e4dc","garden":"#e9efd9","landmark":"#f2d9c4","boathouse":"#d9e6ee","nature":"#e3ecd9"}
def trees(r, n, y0, y1, x0=0, x1=800):
    o=""
    for i in range(n):
        x=r.uniform(x0,x1); y=r.uniform(y0,y1); s=r.uniform(26,52); c=r.choice(["#2e5a3c","#3c6b47","#4f7d4f","#284f36"])
        o+=f'<rect x="{x-3:.0f}" y="{y:.0f}" width="6" height="{s*.6:.0f}" fill="#5a3e2b"/><circle cx="{x:.0f}" cy="{y:.0f}" r="{s/2:.0f}" fill="{c}"/>'
    return o
def icon(k, r):
    if k=="gate": return '<rect x="250" y="170" width="46" height="170" fill="#8a7f70"/><rect x="504" y="170" width="46" height="170" fill="#8a7f70"/><rect x="242" y="156" width="62" height="20" fill="#6d6458"/><rect x="496" y="156" width="62" height="20" fill="#6d6458"/>'+''.join(f'<path d="M{300+i*20} 330 V{205+abs(i-9.5)*3:.0f}" stroke="#1f2a24" stroke-width="5"/>' for i in range(10))+'<path d="M296 214 Q400 186 504 214" stroke="#1f2a24" stroke-width="6" fill="none"/><rect x="330" y="120" width="140" height="34" rx="4" fill="#5a3e2b"/><text x="400" y="143" text-anchor="middle" font-family="sans-serif" font-size="16" font-weight="700" fill="#f4ecd8">CADWALLOW</text>'
    if k=="boathouse": return '<rect x="0" y="300" width="800" height="160" fill="#7fa9c4"/>'+''.join(f'<path d="M{x} {320+i*26} q20 -6 40 0" stroke="#d7ebf0" stroke-width="3" fill="none"/>' for i in range(5) for x in range(30+i*17,800,150))+'<rect x="230" y="190" width="340" height="110" fill="#f4ecd8"/><path d="M200 196 L400 110 L600 196Z" fill="#a8402a"/>'+''.join(f'<rect x="{262+i*76}" y="222" width="42" height="56" fill="#5a3e2b"/>' for i in range(4))+'<rect x="210" y="296" width="380" height="10" fill="#5a3e2b"/><path d="M470 360 q40 18 80 0 l-8 14 h-64z" fill="#c0392b"/><path d="M220 390 q40 18 80 0 l-8 14 h-64z" fill="#f2c14e"/>'
    if k=="play": return '<rect x="0" y="340" width="800" height="120" fill="#c9a77a"/><rect x="230" y="190" width="120" height="16" fill="#2f6fb0"/><rect x="236" y="206" width="10" height="140" fill="#2f6fb0"/><rect x="334" y="206" width="10" height="140" fill="#2f6fb0"/><path d="M344 206 C420 220 440 320 520 340" stroke="#d9822b" stroke-width="22" fill="none"/><path d="M220 190 L290 130 L360 190Z" fill="#c0392b"/><path d="M580 150 L560 340 M680 150 L700 340 M570 150 H690" stroke="#5a3e2b" stroke-width="8"/><path d="M610 150 V280 M650 150 V280" stroke="#1f2a24" stroke-width="3"/><rect x="600" y="280" width="60" height="10" fill="#d4b21f"/>'
    if k=="water": return '<rect x="0" y="330" width="800" height="130" fill="#b9d6df"/>'+''.join(f'<path d="M{x} 330 C{x-10} {250-h} {x+10} {250-h} {x} 330" stroke="#2f6fb0" stroke-width="4" fill="none" opacity=".8"/>' for x,h in [(260,20),(330,60),(400,90),(470,60),(540,20)])+'<path d="M180 330 C180 160 620 160 620 330" stroke="#2e7d4f" stroke-width="18" fill="none"/>'+''.join(f'<circle cx="{r.randint(170,630)}" cy="{r.randint(170,320)}" r="{r.randint(3,7)}" fill="#2f6fb0" opacity=".5"/>' for _ in range(30))
    if k=="field": return '<rect x="0" y="250" width="800" height="210" fill="#7fae5b"/><path d="M400 440 L210 330 L400 260 L590 330Z" fill="#c9a77a"/><path d="M400 440 L210 330 M400 440 L590 330" stroke="#fff" stroke-width="4"/><circle cx="400" cy="345" r="12" fill="#c9a77a" stroke="#fff" stroke-width="3"/>'+''.join(f'<path d="M{x} 250 V110 M{x-22} 110 H{x+22}" stroke="#4b4f52" stroke-width="6"/><rect x="{x-24}" y="96" width="48" height="16" fill="#f2c14e"/>' for x in (120,680))
    if k=="shelter": return '<rect x="0" y="340" width="800" height="120" fill="#8db36b"/><path d="M180 200 L400 110 L620 200Z" fill="#5a3e2b"/><rect x="200" y="196" width="400" height="12" fill="#3e2b1e"/>'+''.join(f'<rect x="{220+i*120}" y="206" width="14" height="140" fill="#3e2b1e"/>' for i in range(4))+'<rect x="270" y="300" width="120" height="12" fill="#a8763e"/><rect x="420" y="300" width="120" height="12" fill="#a8763e"/><rect x="280" y="312" width="8" height="34" fill="#a8763e"/><rect x="372" y="312" width="8" height="34" fill="#a8763e"/><rect x="430" y="312" width="8" height="34" fill="#a8763e"/><rect x="522" y="312" width="8" height="34" fill="#a8763e"/>'
    if k=="restroom": return '<rect x="0" y="340" width="800" height="120" fill="#a9bf8e"/><rect x="270" y="190" width="260" height="150" fill="#d8cbb3"/><path d="M250 196 L400 136 L550 196Z" fill="#2e5a3c"/><rect x="300" y="240" width="60" height="100" fill="#2f6fb0"/><rect x="440" y="240" width="60" height="100" fill="#2f6fb0"/><circle cx="400" cy="230" r="22" fill="#fff"/><text x="400" y="238" text-anchor="middle" font-family="sans-serif" font-weight="700" font-size="20" fill="#2f6fb0">WC</text>'
    if k=="garden": return '<rect x="0" y="330" width="800" height="130" fill="#9cb87a"/><rect x="60" y="210" width="680" height="130" fill="#b8693e"/>'+''.join(f'<path d="M60 {222+i*20} H740" stroke="#9a5530" stroke-width="2"/>' for i in range(6))+'<path d="M330 340 V250 Q400 170 470 250 V340Z" fill="#2e5a3c"/><path d="M350 340 V258 Q400 200 450 258 V340Z" fill="#e9efd9"/>'+''.join(f'<circle cx="{r.randint(80,720)}" cy="{r.randint(350,440)}" r="{r.randint(6,11)}" fill="{r.choice(["#c0392b","#d4b21f","#f4ecd8","#a64d79"])}"/>' for _ in range(40))
    if k=="landmark": return '<path d="M0 360 L250 220 L420 170 L600 230 L800 330 V460 H0Z" fill="#6f8f5a"/>'+''.join(f'<rect x="{350+math.cos(a)*90:.0f}" y="{180+math.sin(a)*22:.0f}" width="22" height="16" fill="#8a7f70"/>' for a in [i*math.pi/4 for i in range(8)])+'<path d="M0 420 Q400 380 800 420 V460 H0Z" fill="#7fa9c4"/><path d="M560 400 v-40 h14 v-22 h12 v30 h10 v-50 h16 v82" fill="#5c6b73"/>'
    if k=="nature": return '<rect x="0" y="300" width="800" height="160" fill="#8fb4a0"/>'+''.join(f'<path d="M{x} 380 l6 -40 l6 40" stroke="#4f7d4f" stroke-width="3" fill="none"/>' for x in range(20,800,24))+'<path d="M0 340 H800 M0 352 H800" stroke="#a8763e" stroke-width="10"/>'+''.join(f'<path d="M{x} 352 V400" stroke="#5a3e2b" stroke-width="6"/>' for x in range(40,800,90))
    return ""
for line in open("places.jsonl"):
    p=json.loads(line); so=p["sort_order"]; k=p["kind"]; r=random.Random(so*13)
    if p["name"]=="Warming Hut":
        body='<rect x="0" y="320" width="800" height="140" fill="#eef3f6"/><path d="M0 380 Q400 350 800 380 V460 H0Z" fill="#cfe0ea"/><rect x="280" y="200" width="240" height="130" fill="#7a5233"/><path d="M260 206 L400 120 L540 206Z" fill="#3e2b1e"/><rect x="470" y="130" width="22" height="50" fill="#6d6458"/><rect x="370" y="250" width="60" height="80" fill="#f2c14e"/><path d="M482 120 q-10 -20 6 -36 q-14 -10 0 -30" stroke="#b0b8bd" stroke-width="5" fill="none"/>'
    else: body=icon(k,r)
    sky=SKY.get(k,"#e6e6dc")
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 460" width="800" height="460"><rect width="800" height="460" fill="{sky}"/><circle cx="{r.randint(560,720)}" cy="{r.randint(60,110)}" r="34" fill="#f4ecd8"/>'+trees(r,9,170,300)+body+f'<rect x="24" y="24" width="64" height="64" rx="32" fill="#1f3d2b"/><text x="56" y="67" text-anchor="middle" font-family="sans-serif" font-weight="700" font-size="28" fill="#f4ecd8">{p["number"]}</text></svg>'
    open(f"art/p-{so:02d}.svg","w").write(svg)
print("art ok")
